"""Pre-extraction vectors captured on 29 October; never regenerated by a test."""
from datetime import date, datetime, timedelta, timezone
from decimal import Decimal as D
import hashlib
import json
from uuid import UUID

import pytest
from apps.reference_api.valuation_policy_contracts import PolicyCreate, PolicyRuleInput
from valuation.economics import canonical_payload, evidence_hash, finite_decimal


@pytest.mark.parametrize('payload,digest', [
    ({'zero': D('-0.000'), 'price': D('100.0000000000000000001'), 'label': 'é £'},
     'b4fd1982eee004379e5d1c10cb90f12a31959331d18a2d2d03ed466a081ecf77'),
    ({'id': UUID(int=1), 'at': datetime(2026, 10, 29, 10, 20, tzinfo=timezone(timedelta(hours=2))),
      'date': date(2026, 10, 29), 'items': (True, None, D('1E-12'))},
     'e04071728655fbf9aa2c3ba25490d69016ab17455f7778cf0a709a7108393962'),
    ({'quantity': D('-125.50'), 'multiplier': D('50'), 'quote_factor': D('100'), 'fx': D('0.749123456789')},
     'a4a859afebc1808c46a6ab5c81f57949c7eb60950f0328b3b988325fec63304c'),
])
def test_existing_evidence_identity(payload, digest):
    assert evidence_hash(payload) == digest
    assert evidence_hash(dict(reversed(list(payload.items())))) == digest


@pytest.mark.parametrize('value,message', [
    (1.5, 'Binary floats are not financial evidence'),
    (datetime(2026, 10, 29), 'Evidence timestamps must be timezone aware'),
    ({1: 'invalid'}, 'Evidence mapping keys must be strings'),
    ({'nested': [D('NaN')]}, 'evidence must be a finite Decimal'),
    (object(), 'Unsupported financial evidence value'),
])
def test_existing_evidence_rejection(value, message):
    with pytest.raises(ValueError, match=message):
        canonical_payload(value)


@pytest.mark.parametrize('value,message', [
    (1, 'amount must be a finite Decimal'),
    (D('Infinity'), 'amount must be a finite Decimal'),
    (D('1e61'), 'amount exceeds supported precision'),
    (D('1e-61'), 'amount exceeds supported precision'),
    (D('1.' + '1' * 60), 'amount exceeds supported precision'),
    (D('0'), 'amount must be positive'),
])
def test_existing_decimal_boundary(value, message):
    with pytest.raises(ValueError, match=message):
        finite_decimal(value, 'amount', positive=True)


@pytest.mark.parametrize('model,digest', [
    (PolicyCreate, '56cb0b788d7d9b9b1ba1edad560b4f2c49b129b2814ab990e6062dbd2f6986f6'),
    (PolicyRuleInput, '52acb96346cce8b9ba5e90b2d1ef76ebbeb2daca7b105880a130602016af3882'),
])
def test_existing_command_schema(model, digest):
    encoded = json.dumps(model.model_json_schema(by_alias=True), sort_keys=True, separators=(',', ':'))
    assert hashlib.sha256(encoded.encode()).hexdigest() == digest


def test_compatibility_exports_are_the_shared_objects():
    from security_master_schema import evidence
    from market_data import pricing_policy_contracts
    from apps.reference_api import booking_controls, product_booking, repository
    from security_master_schema.booking_controls import booking_lock_key
    from security_master_schema.reference_visibility import require_visible
    from security_master_schema.market_data_visibility import catalogue_subject_clause
    assert evidence_hash is evidence.evidence_hash
    assert finite_decimal is evidence.finite_decimal
    assert canonical_payload is evidence.canonical_payload
    assert PolicyCreate is pricing_policy_contracts.PolicyCreate
    assert PolicyRuleInput is pricing_policy_contracts.PolicyRuleInput
    assert booking_controls.booking_lock_key is booking_lock_key
    assert product_booking.require_visible is require_visible
    assert repository._market_data_visible_node_clause is catalogue_subject_clause
